#!/usr/bin/env node
// Generated by scripts/build-skill.mjs from scripts/skill/save_tmp.mjs in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
// Keep a drawcast on drawcast's server for a while and print a short link that
// plays it: https://www.drawcast.app/#tmp=<id>.
//
//   node save_tmp.mjs cast.yaml
//   node save_tmp.mjs < cast.yaml
//
// No account and no key. Temporary means temporary: the link works for
// minutes to a day, depending on how busy the server is, and nothing is
// promised. The text only (at most 100 KB): no recorded narration. For a link
// that lasts, save the drawcast on GitHub (save_github.mjs). Node 18 or later.
import { readFileSync, realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const API = "https://drawcast.anvil.app";
export const MAX_BYTES = 100 * 1024;

/** Keeps `text` for a while: {link, expires} (the latest it can last). Throws with the server's reason. */
export async function keepForAWhile(text, { api = API, fetchImpl = fetch } = {}) {
  if (!text || !text.trim()) throw new Error("The drawcast is empty.");
  if (Buffer.byteLength(text, "utf8") > MAX_BYTES) throw new Error(`Too big to keep (over ${MAX_BYTES / 1024} KB): save it on GitHub instead.`);
  const res = await fetchImpl(`${api.replace(/\/+$/, "")}/_/api/tmp/put`, {
    method: "POST",
    headers: { "content-type": "text/plain" },
    body: JSON.stringify({ cast: text }),
    signal: AbortSignal.timeout(30_000),
  });
  let body = {};
  try {
    body = await res.json();
  } catch {
    /* the status says enough */
  }
  if (!res.ok || typeof body.link !== "string") throw new Error(body.message ?? `The drawcast server refused it (HTTP ${res.status}).`);
  return { link: body.link, expires: body.expires };
}

async function main(argv) {
  const file = argv.find((a) => !a.startsWith("--"));
  let bytes = file ? readFileSync(file) : readFileSync(0);
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) bytes = bytes.subarray(3);
  const text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  try {
    const { link } = await keepForAWhile(text);
    console.log(link);
    console.error("temporary: the link works for minutes to a day, no promise — save it on GitHub for one that lasts");
    return 0;
  } catch (err) {
    console.error(err.message);
    return 1;
  }
}

if (process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))) process.exitCode = await main(process.argv.slice(2));
